/bin/bash -c "node --input-type=module <<'NODE'
const base = 'http://localhost:3127/'
const before = await (await fetch(base)).text()
const actionId = before.match(/name=\"\\"'$ACTION_ID_([''^"]+)"/i)?.[1]
console.log('"'Form action ID present:', Boolean(actionId))
if ("'!actionId) process.exit(1)
const title = `Fresh post ${Date.now()}`
const form = new FormData()
form.set(`$ACTION_ID_${actionId}`, '"'')
form.set('title', title)
form.set('content', 'Test content')
const submitted = await fetch(base, { method: 'POST', body: form, redirect: 'follow' })
const after = await submitted.text()
console.log('Submission status:', submitted.status)
console.log('New post appears immediately:', after.includes(title))
const next = await (await fetch(base)).text()
console.log('New post appears on next page load:', next.includes(title))
if ("'!after.includes(title) || !next.includes(title)) process.exitCode = 1
NODE'
